/** Material Symbols use a 960×960 grid whose y-axis runs from -960 to 0, hence the shift. */
private fun symbol(name: String, vararg paths: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
    ).apply {
        addGroup(translationY = 960f)
        paths.forEach { addPath(pathData = addPathNodes(it), fill = SolidColor(Color.Black)) }
        clearGroup()
    }.build()
